"use client";

import { ChangeEvent, Dispatch, ReactNode, SetStateAction, useEffect, useMemo, useRef, useState } from "react";
import { allocationSubtotal, allocationTotal, allocatedQuantity, matchDefinition, requirementTotal, safeSpreadsheetText, unallocatedQuantity } from "./budget-domain.mjs";
import { ElliesBookWorkbench, WorkbenchStudioData } from "./ellies-book-workbench";

type WorkspaceView = "plan" | "spend" | "monitor";
type TopTab = "profile" | "library" | "plan" | "spend" | "monitor";
type Mode = "working" | "training";
type Quarter = "Q1" | "Q2" | "Q3" | "Q4";
type DocumentType = "Quotation" | "Purchase order" | "Invoice";
type RevisionStatus = "Proposed" | "Adjusted";
type SelectionMode = "single" | "multi";
type DefinitionScope = "Reusable" | "Project-only";
type DefinitionLifecycle = "Active" | "Candidate" | "Merged" | "Retired";
type SourceType = "External vendor" | "Internal warehouse" | "Local replenishment" | "Existing inventory" | "Other";
type ReviewStatus = "Unreviewed" | "Needs review" | "Confirmed" | "Rejected";
type CandidateStatus = "Pending" | "Promoted" | "Merged" | "Kept project-only" | "Deferred" | "Retired";
type RecommendationEngine = "Rules" | "Model";
type RecommendationStatus = "Suggested" | "Accepted" | "Rejected";

const QUARTERS: Quarter[] = ["Q1", "Q2", "Q3", "Q4"];
const CURRENCIES = ["USD", "SGD", "EUR", "GBP", "AUD"];
const MEASUREMENT_WINDOWS = ["Weekly", "Bi-weekly", "Monthly", "Quarterly", "Semi-annually", "Annually", "At project completion"];
const WORKING_KEY = "function-budget-studio-v1-4-working";
const TRAINING_KEY = "function-budget-studio-v1-4-multiline-training";
const LEGACY_WORKING_KEY = "function-budget-studio-v1-3-working";
const LEGACY_TRAINING_KEY = "function-budget-studio-v1-3-training";
const presets = ["Marketing & Brand", "People Operations", "Technology / IT", "Customer Support", "Retail Operations"];

type Profile = { functionName: string; plannerName: string; team: string };
type TeamMember = { id: string; name: string; role: string };
type FxRate = { from: string; to: string; rate: number };
type BudgetSettings = { currency: string; fiscalPeriod: string; currentQuarter: Quarter; fiscalYearStartMonth: number; fiscalYearStartYear: number; fxVersion: string; fxRates: FxRate[]; teamMembers: TeamMember[]; nextProjectSequence: number };
type TagValue = { id: string; name: string; code: string };
type TagFamily = { id: string; name: string; priority: number; includeInProjectId: boolean; selection: SelectionMode; values: TagValue[] };
type DefinitionBase = { id: string; name: string; tagIds: string[]; scope?: DefinitionScope; lifecycle?: DefinitionLifecycle; originProjectId?: string; aliases?: string[]; sourceText?: string; mergedIntoId?: string; createdAt?: string; reviewedAt?: string; reviewerNote?: string };
type SpendingItemDefinition = DefinitionBase & { glCode: string; financeDescription: string; mappingStatus: "Confirmed" | "Needs Finance review"; unitOfMeasure?: string; specification?: string };
type OutcomeDefinition = DefinitionBase & { definition: string; unit: string; measurementWindow: string; direction?: string; expectedEvidenceSource?: string; effectiveDate?: string };
type Library = { tagFamilies: TagFamily[]; spendingItems: SpendingItemDefinition[]; outcomes: OutcomeDefinition[] };
type ProjectWorkPackage = { id: string; name: string; description?: string; tagIds: string[] };
type SourcingAllocation = { id: string; sourceType: SourceType; vendorOrWarehouse: string; sourceCountry: string; sourceLocation: string; quantity: number; unitPrice: number; currency: string; quarter: Quarter; priceBasis: string; additionalCostEstimate: number; notes: string; financeMappingStatus: "Suggested" | "Confirmed" | "Needs Finance review"; suggestedFinanceCode?: string; confirmedFinanceCode?: string; mappingRationale: string; linkedDocumentId?: string; linkedDocumentLineId?: string };
type ProjectSpendLine = { id: string; spendingItemId: string; itemNameSnapshot?: string; specification?: string; unitOfMeasure?: string; sourceText?: string; quantity: number; unitPrice: number; unitCurrency: string; quarters: Quarter[]; workPackageId?: string; allocations?: SourcingAllocation[]; adjustmentComment?: string };
type ProjectOutcome = { id: string; outcomeDefinitionId: string; outcomeNameSnapshot?: string; baseline: string; target: string; current: string; accountableOwner: string; adjustmentComment?: string };
type BudgetRevision = { id: string; status: RevisionStatus; versionType?: "Original" | "Adjustment"; timestamp: string; comment: string; lines: ProjectSpendLine[]; outcomes: ProjectOutcome[]; approvedAmount: number; approvedCurrency: string; approvedComment: string; plannedTotal: number; changedFields: string[] };
type Project = { id: string; recordId: string; generatedId: string; idSnapshot?: string; name: string; purpose: string; description: string; tagIds: string[]; period: string; spendingQuarters: Quarter[]; ownerIds: string[]; legacyOwner?: string; workPackages?: ProjectWorkPackage[]; lines: ProjectSpendLine[]; outcomes: ProjectOutcome[]; approvedAmount: number; approvedCurrency: string; approvedAdjustmentComment?: string; revisions: BudgetRevision[]; currentRevisionId?: string };
type DocumentLine = { id: string; projectId: string; spendingLineId: string; allocationId?: string; description: string; amount: number; currency: string; spendQuarter: Quarter; sourceDocumentId?: string; sourceDocumentLineId?: string };
type SpendDocument = { id: string; type: DocumentType; fileName: string; reference: string; projectId?: string; date: string; vendor: string; status: string; source?: "Synthetic" | "Local upload"; lines: DocumentLine[] };
type CurationCandidate = { id: string; definitionId: string; definitionType: "Spending item" | "Outcome"; originProjectId: string; originalSourceWording: string; proposedName: string; suggestedTagIds: string[]; possibleDuplicateIds: string[]; status: CandidateStatus; reviewerNote: string; createdAt: string; reviewedAt?: string };
type ImportReviewRecord = { id: string; projectId: string; rawRow: string[]; interpretedDescription: string; suggestedProjectId?: string; suggestedWorkPackageId?: string; suggestedItemId?: string; suggestedAllocation?: Partial<SourcingAllocation>; matchMethod: string; reviewStatus: ReviewStatus; reviewerNote: string; confirmedAt?: string };
type Recommendation = { id: string; targetRecordId: string; targetField: string; proposedValue: string; matchStrength: "Low" | "Medium" | "High"; rationale: string; supportingSourceRefs: string[]; engine: RecommendationEngine; status: RecommendationStatus };
type StudioData = { schemaVersion: number; profile: Profile; settings: BudgetSettings; library: Library; libraryComplete: boolean; projects: Project[]; documents: SpendDocument[]; curationCandidates: CurationCandidate[]; importReviews: ImportReviewRecord[]; recommendations: Recommendation[] };
type ValidationError = { key: string; message: string };

function newId(prefix: string) { if (typeof crypto !== "undefined" && "randomUUID" in crypto) return `${prefix}-${crypto.randomUUID()}`; return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function number(value: string | number) { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : 0; }
function formatMoney(value: number, currency: string) { try { return new Intl.NumberFormat("en-US", { style: "currency", currency: currency || "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number.isFinite(value) ? value : 0); } catch { return `${currency || "USD"} ${(Number.isFinite(value) ? value : 0).toFixed(2)}`; } }
function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T; }
function slug(value: string) { return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "member"; }
function codeForName(name: string) { const known: Record<string, string> = { Gucci: "GUC", Lancaster: "LNC", Burberry: "BUR", "Make-up": "MU", Perfume: "FRAG" }; if (known[name]) return known[name]; const words = name.toUpperCase().match(/[A-Z0-9]+/g) ?? []; return (words.length > 1 ? words.map((word) => word[0]).join("") : (words[0] ?? "TAG").slice(0, 3)).slice(0, 8); }
function blankLibrary(): Library { return { tagFamilies: [], spendingItems: [], outcomes: [] }; }
function usdPerUnit(currency: string) { return ({ USD: 1, SGD: 0.74, EUR: 1.08, GBP: 1.27, AUD: 0.66 } as Record<string, number>)[currency] ?? 1; }
function defaultFxRates(to = "USD") { return CURRENCIES.map((from) => ({ from, to, rate: Number((usdPerUnit(from) / usdPerUnit(to)).toFixed(6)) })); }
function defaultMembers(profile?: Profile) { return profile?.plannerName ? [{ id: `member-${slug(profile.plannerName)}`, name: profile.plannerName, role: "Planner" }] : []; }
function fiscalPeriodForDate(settings: Pick<BudgetSettings, "fiscalYearStartMonth" | "fiscalYearStartYear">, date = new Date()) { const startMonth = Math.min(12, Math.max(1, number(settings.fiscalYearStartMonth) || 6)); const startYear = Math.max(2000, number(settings.fiscalYearStartYear) || date.getFullYear()); const month = date.getMonth() + 1; const year = date.getFullYear(); const fiscalYear = Math.max(startYear + 1, month >= startMonth ? year + 1 : year); const monthsSinceStart = (month - startMonth + 12) % 12; return { fiscalYear: `FY${String(fiscalYear).slice(-2)}`, quarter: `Q${Math.floor(monthsSinceStart / 3) + 1}` as Quarter, label: `${`FY${String(fiscalYear).slice(-2)}`} Q${Math.floor(monthsSinceStart / 3) + 1}` }; }
function nowIso() { return new Date().toISOString(); }
function blankData(): StudioData { const settings = { currency: "USD", fiscalPeriod: "FY2027", currentQuarter: "Q1" as Quarter, fiscalYearStartMonth: 6, fiscalYearStartYear: 2026, fxVersion: "Illustrative fixed rates v1", fxRates: defaultFxRates(), teamMembers: [], nextProjectSequence: 1 }; const calculated = fiscalPeriodForDate(settings); return { schemaVersion: 2, profile: { functionName: "", plannerName: "", team: "" }, settings: { ...settings, fiscalPeriod: calculated.fiscalYear, currentQuarter: calculated.quarter }, library: blankLibrary(), libraryComplete: false, projects: [], documents: [], curationCandidates: [], importReviews: [], recommendations: [] }; }

function starterLibrary(functionName: string): Library {
  const marketing = /marketing|brand|visual merchandising/i.test(functionName);
  return {
    tagFamilies: [
      { id: "tag-business-intent", name: "Business intent", priority: 1, includeInProjectId: true, selection: "single", values: [{ id: "tag-intent-growth", name: "Growth", code: "GROWTH" }, { id: "tag-intent-efficiency", name: "Efficiency", code: "EFF" }, { id: "tag-intent-capability", name: "Capability", code: "CAP" }] },
      { id: "tag-brand-house", name: "Brand house", priority: 2, includeInProjectId: true, selection: "single", values: [{ id: "tag-gucci", name: "Gucci", code: "GUC" }, { id: "tag-lancaster", name: "Lancaster", code: "LNC" }, { id: "tag-burberry", name: "Burberry", code: "BUR" }] },
      { id: "tag-product-category", name: "Product category", priority: 3, includeInProjectId: true, selection: "multi", values: [{ id: "tag-makeup", name: "Make-up", code: "MU" }, { id: "tag-perfume", name: "Perfume", code: "FRAG" }] },
      { id: "tag-project-type", name: "Project type", priority: 4, includeInProjectId: false, selection: "single", values: marketing ? [{ id: "tag-campaign", name: "Campaign", code: "CMP" }, { id: "tag-store", name: "Store activation", code: "STA" }, { id: "tag-ops", name: "Recurring operations", code: "OPS" }] : [{ id: "tag-initiative", name: "Initiative", code: "INI" }, { id: "tag-ops", name: "Recurring operations", code: "OPS" }] },
      { id: "tag-channel", name: "Channel", priority: 5, includeInProjectId: false, selection: "single", values: [{ id: "tag-internal", name: "Internal", code: "INT" }, { id: "tag-external", name: "External", code: "EXT" }] },
    ],
    spendingItems: marketing ? [
      { id: "spend-posm", name: "Shelf tester unit", glCode: "001230", financeDescription: "Illustrative point-of-sale marketing material.", tagIds: ["tag-gucci", "tag-makeup", "tag-internal"], mappingStatus: "Confirmed" },
      { id: "spend-media", name: "Paid media package", glCode: "001245", financeDescription: "Illustrative paid distribution package.", tagIds: ["tag-external"], mappingStatus: "Confirmed" },
      { id: "spend-research", name: "Market research sprint", glCode: "001280", financeDescription: "Illustrative customer or market research service.", tagIds: ["tag-external"], mappingStatus: "Confirmed" },
    ] : [
      { id: "spend-service", name: "Core service package", glCode: "", financeDescription: "Illustrative function service or operating item.", tagIds: ["tag-internal"], mappingStatus: "Needs Finance review" },
      { id: "spend-tool", name: "Function tool subscription", glCode: "", financeDescription: "Illustrative recurring tool or system cost.", tagIds: ["tag-external"], mappingStatus: "Needs Finance review" },
    ],
    outcomes: marketing ? [
      { id: "kpi-pipeline", name: "Qualified pipeline contribution", definition: "Qualified opportunities associated with the project window.", unit: "qualified opportunities", measurementWindow: "Quarterly", tagIds: ["tag-campaign"] },
      { id: "kpi-shelf", name: "Shelf execution coverage", definition: "Share of planned placements installed and checked.", unit: "% of placements", measurementWindow: "At project completion", tagIds: ["tag-store"] },
      { id: "kpi-efficiency", name: "Cost per qualified opportunity", definition: "Project spend divided by qualified opportunities.", unit: "USD / opportunity", measurementWindow: "Monthly", tagIds: ["tag-campaign"] },
    ] : [
      { id: "kpi-service", name: "Service delivery coverage", definition: "Share of function service commitments delivered in the period.", unit: "% delivered", measurementWindow: "Monthly", tagIds: ["tag-ops"] },
      { id: "kpi-capability", name: "Capability adoption", definition: "Share of intended users or teams adopting the capability.", unit: "% adoption", measurementWindow: "Quarterly", tagIds: ["tag-initiative"] },
    ],
  };
}

function normalizeDefinitionBase<T extends DefinitionBase>(definition: T, originProjectId?: string): T {
  return { ...definition, scope: definition.scope ?? "Reusable", lifecycle: definition.lifecycle ?? "Active", originProjectId: definition.originProjectId ?? originProjectId, aliases: definition.aliases ?? [], sourceText: definition.sourceText ?? definition.name ?? "", createdAt: definition.createdAt ?? nowIso() };
}
function defaultWorkPackage(): ProjectWorkPackage { return { id: newId("work-package"), name: "General", description: "General project expenditure", tagIds: [] }; }
function normalizeAllocation(allocation: Partial<SourcingAllocation>, settings: BudgetSettings): SourcingAllocation { return { id: allocation.id ?? newId("allocation"), sourceType: allocation.sourceType ?? "External vendor", vendorOrWarehouse: allocation.vendorOrWarehouse ?? "", sourceCountry: allocation.sourceCountry ?? "", sourceLocation: allocation.sourceLocation ?? "", quantity: number(allocation.quantity ?? 0), unitPrice: number(allocation.unitPrice ?? 0), currency: allocation.currency ?? settings.currency, quarter: QUARTERS.includes(allocation.quarter as Quarter) ? allocation.quarter as Quarter : settings.currentQuarter, priceBasis: allocation.priceBasis ?? "Unit price", additionalCostEstimate: number(allocation.additionalCostEstimate ?? 0), notes: allocation.notes ?? "", financeMappingStatus: allocation.financeMappingStatus ?? "Needs Finance review", suggestedFinanceCode: allocation.suggestedFinanceCode, confirmedFinanceCode: allocation.confirmedFinanceCode, mappingRationale: allocation.mappingRationale ?? "", linkedDocumentId: allocation.linkedDocumentId, linkedDocumentLineId: allocation.linkedDocumentLineId }; }
function normalizeWorkPackages(raw: Partial<Project>): ProjectWorkPackage[] { const packages = (raw.workPackages ?? []).map((workPackage) => ({ id: workPackage.id ?? newId("work-package"), name: workPackage.name ?? "General", description: workPackage.description ?? "", tagIds: workPackage.tagIds ?? [] })); return packages.length ? packages : [defaultWorkPackage()]; }

function normalizeData(raw: Partial<StudioData> | null | undefined): StudioData {
  const base = blankData();
  const profile = { ...base.profile, ...(raw?.profile ?? {}) };
  const rawSettings = raw?.settings ?? {} as BudgetSettings;
  const rawFamilies = raw?.library?.tagFamilies ?? [];
  const tagFamilies: TagFamily[] = rawFamilies.map((family, index) => ({
    id: family.id || newId("family"), name: family.name ?? "", priority: number((family as Partial<TagFamily>).priority ?? (index + 1)), includeInProjectId: Boolean((family as Partial<TagFamily>).includeInProjectId ?? /brand house|product category/i.test(family.name ?? "")), selection: ((family as Partial<TagFamily>).selection ?? (/product category/i.test(family.name ?? "") ? "multi" : "single")) as SelectionMode,
    values: (family.values ?? []).map((value) => ({ id: value.id || newId("tag"), name: value.name ?? "", code: (value as Partial<TagValue>).code || codeForName(value.name ?? "") })),
  }));
  const library: Library = { tagFamilies, spendingItems: (raw?.library?.spendingItems ?? []).map((item) => normalizeDefinitionBase({ ...item, name: item.name ?? "", glCode: item.glCode ?? "", financeDescription: item.financeDescription ?? "", tagIds: item.tagIds ?? [], mappingStatus: item.mappingStatus ?? "Needs Finance review", unitOfMeasure: item.unitOfMeasure ?? "", specification: item.specification ?? "" } as SpendingItemDefinition)), outcomes: (raw?.library?.outcomes ?? []).map((outcome) => normalizeDefinitionBase({ ...outcome, name: outcome.name ?? "", definition: outcome.definition ?? "", unit: outcome.unit ?? "", measurementWindow: outcome.measurementWindow ?? "Monthly", tagIds: outcome.tagIds ?? [], direction: outcome.direction ?? "Increase", expectedEvidenceSource: outcome.expectedEvidenceSource ?? "", effectiveDate: outcome.effectiveDate ?? "" } as OutcomeDefinition)) };
  const members = ((rawSettings as Partial<BudgetSettings>).teamMembers ?? []).map((member) => ({ id: member.id || newId("member"), name: member.name ?? "", role: member.role ?? "Team member" }));
  for (const member of defaultMembers(profile)) if (!members.some((candidate) => candidate.name === member.name)) members.push(member);
  const knownOwnerNames = (raw?.projects ?? []).map((project) => (project as Partial<Project>).legacyOwner ?? (project as Partial<Project> & { owner?: string }).owner ?? "").filter(Boolean);
  for (const name of knownOwnerNames) if (!members.some((member) => member.name === name)) members.push({ id: `member-${slug(name)}`, name, role: "Historical owner" });
  const maxSequence = (raw?.projects ?? []).reduce((max, project) => { const match = String(project.id ?? "").match(/(\d{4})$/); return Math.max(max, match ? Number(match[1]) : 0); }, 0);
  const settings: BudgetSettings = { ...base.settings, ...rawSettings, currency: rawSettings.currency || "USD", fiscalYearStartMonth: number((rawSettings as Partial<BudgetSettings>).fiscalYearStartMonth) || 6, fiscalYearStartYear: number((rawSettings as Partial<BudgetSettings>).fiscalYearStartYear) || 2026, currentQuarter: QUARTERS.includes(rawSettings.currentQuarter as Quarter) ? rawSettings.currentQuarter as Quarter : base.settings.currentQuarter, fxVersion: rawSettings.fxVersion || "Illustrative fixed rates v1", fxRates: rawSettings.fxRates?.length ? rawSettings.fxRates : defaultFxRates(rawSettings.currency || "USD"), teamMembers: members, nextProjectSequence: Math.max(number(rawSettings.nextProjectSequence), maxSequence + 1, 1) };
  const calculatedPeriod = fiscalPeriodForDate(settings);
  settings.fiscalPeriod = calculatedPeriod.fiscalYear;
  settings.currentQuarter = calculatedPeriod.quarter;
  const projects = (raw?.projects ?? []).map((project) => {
    const legacyOwner = (project as Partial<Project> & { owner?: string }).owner ?? "";
    const ownerIds = (project as Partial<Project>).ownerIds?.length ? (project as Partial<Project>).ownerIds! : legacyOwner ? [members.find((member) => member.name === legacyOwner)?.id ?? `member-${slug(legacyOwner)}`] : [];
    const workPackages = normalizeWorkPackages(project);
    const generalPackage = workPackages[0];
    const lines = (project.lines ?? []).map((line) => { const partial = line as Partial<ProjectSpendLine>; const item = (raw?.library?.spendingItems ?? []).find((candidate) => candidate.id === line.spendingItemId); return { ...line, quantity: number(line.quantity), unitPrice: number(line.unitPrice), unitCurrency: partial.unitCurrency || settings.currency, itemNameSnapshot: partial.itemNameSnapshot ?? item?.name ?? "", specification: partial.specification ?? "", unitOfMeasure: partial.unitOfMeasure ?? item?.unitOfMeasure ?? "", sourceText: partial.sourceText ?? item?.sourceText ?? item?.name ?? "", workPackageId: partial.workPackageId ?? generalPackage.id, allocations: (partial.allocations ?? []).map((allocation) => normalizeAllocation(allocation, settings)), quarters: (line.quarters ?? []).filter((quarter): quarter is Quarter => QUARTERS.includes(quarter as Quarter)), adjustmentComment: partial.adjustmentComment ?? "" }; });
    const outcomes = (project.outcomes ?? []).map((outcome) => ({ ...outcome, adjustmentComment: (outcome as Partial<ProjectOutcome>).adjustmentComment ?? "" }));
    const revisions = (project.revisions ?? []).map((revision, index) => ({ ...revision, versionType: (revision as Partial<BudgetRevision>).versionType ?? (index === 0 ? "Original" : "Adjustment"), lines: (revision.lines ?? lines).map((line) => ({ ...line, unitCurrency: (line as Partial<ProjectSpendLine>).unitCurrency || settings.currency, itemNameSnapshot: (line as Partial<ProjectSpendLine>).itemNameSnapshot ?? "", specification: (line as Partial<ProjectSpendLine>).specification ?? "", unitOfMeasure: (line as Partial<ProjectSpendLine>).unitOfMeasure ?? "", sourceText: (line as Partial<ProjectSpendLine>).sourceText ?? "", workPackageId: (line as Partial<ProjectSpendLine>).workPackageId ?? generalPackage.id, allocations: ((line as Partial<ProjectSpendLine>).allocations ?? []).map((allocation) => normalizeAllocation(allocation, settings)), adjustmentComment: (line as Partial<ProjectSpendLine>).adjustmentComment ?? "" })), outcomes: (revision as Partial<BudgetRevision>).outcomes ?? outcomes, approvedAmount: number((revision as Partial<BudgetRevision>).approvedAmount ?? project.approvedAmount), approvedCurrency: (revision as Partial<BudgetRevision>).approvedCurrency ?? (project as Partial<Project>).approvedCurrency ?? settings.currency, approvedComment: (revision as Partial<BudgetRevision>).approvedComment ?? "", plannedTotal: number(revision.plannedTotal), changedFields: (revision as Partial<BudgetRevision>).changedFields ?? [] }));
    const projectTypeTagId = (project as Partial<Project> & { projectTypeTagId?: string }).projectTypeTagId;
    const tagIds = Array.from(new Set([...(project.tagIds ?? []), ...(projectTypeTagId ? [projectTypeTagId] : [])]));
    return { id: project.id ?? newId("project"), recordId: (project as Partial<Project>).recordId ?? `record-${project.id ?? newId("project")}`, generatedId: (project as Partial<Project>).generatedId ?? project.id ?? "PROJECT-LEGACY", idSnapshot: (project as Partial<Project>).idSnapshot, name: project.name ?? "", purpose: (project as Partial<Project>).purpose ?? "", description: project.description ?? "", tagIds, period: project.period ?? settings.fiscalPeriod, spendingQuarters: (project.spendingQuarters ?? []).filter((quarter): quarter is Quarter => QUARTERS.includes(quarter as Quarter)), ownerIds, legacyOwner, workPackages, lines, outcomes, approvedAmount: number(project.approvedAmount), approvedCurrency: (project as Partial<Project>).approvedCurrency ?? settings.currency, approvedAdjustmentComment: (project as Partial<Project>).approvedAdjustmentComment ?? "", revisions, currentRevisionId: project.currentRevisionId } as Project;
  });
  const documents = (raw?.documents ?? []).map((document) => ({ ...document, source: (document as Partial<SpendDocument>).source ?? "Synthetic", projectId: document.projectId, lines: (document.lines ?? []).map((line) => ({ ...line, amount: number(line.amount), currency: (line as Partial<DocumentLine>).currency ?? settings.currency, spendQuarter: QUARTERS.includes((line as Partial<DocumentLine>).spendQuarter as Quarter) ? (line as Partial<DocumentLine>).spendQuarter as Quarter : settings.currentQuarter, allocationId: (line as Partial<DocumentLine>).allocationId, sourceDocumentLineId: (line as Partial<DocumentLine>).sourceDocumentLineId })) }));
  const candidates = (raw?.curationCandidates ?? []).map((candidate) => ({ ...candidate, suggestedTagIds: candidate.suggestedTagIds ?? [], possibleDuplicateIds: candidate.possibleDuplicateIds ?? [], reviewerNote: candidate.reviewerNote ?? "", status: candidate.status ?? "Pending", createdAt: candidate.createdAt ?? nowIso() }));
  const importReviews = (raw?.importReviews ?? []).map((review) => ({ ...review, rawRow: review.rawRow ?? [], matchMethod: review.matchMethod ?? "Unmatched", reviewStatus: review.reviewStatus ?? "Unreviewed", reviewerNote: review.reviewerNote ?? "" }));
  const recommendations = (raw?.recommendations ?? []).map((recommendation) => ({ ...recommendation, supportingSourceRefs: recommendation.supportingSourceRefs ?? [], engine: recommendation.engine ?? "Rules", status: recommendation.status ?? "Suggested" }));
  return { schemaVersion: number(raw?.schemaVersion ?? 2), profile, settings, library, libraryComplete: Boolean(raw?.libraryComplete), projects, documents, curationCandidates: candidates, importReviews, recommendations };
}

function lineAllocations(line: ProjectSpendLine) { return line.allocations ?? []; }
function lineTotal(line: ProjectSpendLine) { return requirementTotal({ quantity: line.quantity, unitPrice: line.unitPrice, allocations: lineAllocations(line) }); }
function rateFor(data: StudioData, from: string) { if (from === data.settings.currency) return 1; return data.settings.fxRates.find((rate) => rate.from === from && rate.to === data.settings.currency)?.rate ?? 1; }
function reportingAmount(data: StudioData, amount: number, currency: string) { return amount * rateFor(data, currency); }
function lineTotalReporting(data: StudioData, line: ProjectSpendLine) { const allocations = lineAllocations(line); return allocations.length ? allocations.reduce((sum, allocation) => sum + reportingAmount(data, allocationSubtotal(allocation), allocation.currency), 0) : reportingAmount(data, lineTotal(line), line.unitCurrency); }
function projectPlannedReporting(data: StudioData, project: Project) { return project.lines.reduce((sum, line) => sum + lineTotalReporting(data, line), 0); }
function approvedReporting(data: StudioData, project: Project) { return reportingAmount(data, project.approvedAmount, project.approvedCurrency); }
function revisionStatus(project: Project) { return project.revisions.find((revision) => revision.id === project.currentRevisionId)?.status ?? "Proposed"; }
function revisionTimestamp(project: Project) { return project.revisions.find((revision) => revision.id === project.currentRevisionId)?.timestamp ?? ""; }
function quarterIndex(quarter: Quarter) { return QUARTERS.indexOf(quarter); }
function isYtg(quarter: Quarter, current: Quarter) { return quarterIndex(quarter) >= quarterIndex(current); }
function quarterAmount(data: StudioData, line: ProjectSpendLine, quarter: Quarter) { const allocations = lineAllocations(line); if (allocations.length) return allocations.filter((allocation) => allocation.quarter === quarter).reduce((sum, allocation) => sum + reportingAmount(data, allocationSubtotal(allocation), allocation.currency), 0); if (!line.quarters.includes(quarter)) return 0; const ordered = line.quarters.slice().sort((a, b) => quarterIndex(a) - quarterIndex(b)); const cents = Math.round(lineTotalReporting(data, line) * 100); const base = Math.floor(cents / Math.max(1, ordered.length)); const remainder = cents - (base * Math.max(1, ordered.length - 1)); return (ordered.indexOf(quarter) === ordered.length - 1 ? remainder : base) / 100; }
function tagValueFor(data: StudioData, id: string) { for (const family of data.library.tagFamilies) { const value = family.values.find((candidate) => candidate.id === id); if (value) return { family, value }; } return undefined; }
function itemFor(data: StudioData, id: string) { return data.library.spendingItems.find((item) => item.id === id); }
function outcomeFor(data: StudioData, id: string) { return data.library.outcomes.find((outcome) => outcome.id === id); }
function projectTypeFamily(data: StudioData) { return data.library.tagFamilies.find((family) => family.name.trim().toLowerCase() === "project type"); }
function projectTypeTagId(data: StudioData, project: Project) { const family = projectTypeFamily(data); return project.tagIds.find((tagId) => tagValueFor(data, tagId)?.family.id === family?.id) ?? ""; }
function tagNames(data: StudioData, ids: string[]) { return ids.map((id) => tagValueFor(data, id)?.value.name).filter(Boolean).join(" · "); }
function ownerNames(data: StudioData, ids: string[], legacy = "") { const names = ids.map((id) => data.settings.teamMembers.find((member) => member.id === id)?.name).filter(Boolean) as string[]; return names.length ? names.join(", ") : legacy || "Unassigned"; }
function dateLabel(timestamp: string) { try { return new Intl.DateTimeFormat("en-SG", { dateStyle: "medium", timeStyle: "short" }).format(new Date(timestamp)); } catch { return timestamp; } }
function idPrefix(data: StudioData, tagIds: string[]) { return data.library.tagFamilies.filter((family) => family.includeInProjectId).sort((a, b) => a.priority - b.priority).map((family) => family.values.filter((value) => tagIds.includes(value.id)).sort((a, b) => a.code.localeCompare(b.code)).map((value) => value.code).join("+")).filter(Boolean).join("-") || "PROJECT"; }
function nextProjectId(data: StudioData, tagIds: string[]) { return `${idPrefix(data, tagIds)}-${String(data.settings.nextProjectSequence).padStart(4, "0")}`; }
function projectIdSnapshot(data: StudioData, tagIds: string[]) { return data.library.tagFamilies.filter((family) => family.includeInProjectId).sort((a, b) => a.priority - b.priority).map((family) => `${family.priority}:${family.name}=${family.values.filter((value) => tagIds.includes(value.id)).map((value) => `${value.name}(${value.code})`).join("+")}`).filter((part) => !part.endsWith("=")).join(" | "); }
function confirmRemoval(label: string) { return typeof window === "undefined" || window.confirm(`Remove ${label}? This cannot be undone.`); }
function projectSequence(project: Project) { const match = `${project.generatedId || project.id}`.match(/-(\d{3,})$/); return match ? Number(match[1]) : undefined; }
function rekeyProjectIdentifiers(data: StudioData, projects: Project[]) {
  const originalIds = new Set(projects.map((project) => project.id)); const used = new Set<string>(); const remap = new Map<string, string>(); let nextSequence = Math.max(1, data.settings.nextProjectSequence);
  const nextProjects = projects.map((project) => { const preferred = projectSequence(project); let sequence = preferred ?? nextSequence; let candidate = `${idPrefix(data, project.tagIds)}-${String(sequence).padStart(4, "0")}`; const available = () => !used.has(candidate) && (candidate === project.id || !originalIds.has(candidate)); if (!available()) { sequence = Math.max(nextSequence, 1); candidate = `${idPrefix(data, project.tagIds)}-${String(sequence).padStart(4, "0")}`; while (!available()) { sequence += 1; candidate = `${idPrefix(data, project.tagIds)}-${String(sequence).padStart(4, "0")}`; } } if (sequence >= nextSequence) nextSequence = sequence + 1; used.add(candidate); remap.set(project.id, candidate); return { ...project, id: candidate, generatedId: candidate, idSnapshot: projectIdSnapshot(data, project.tagIds) }; });
  const documents = data.documents.map((document) => ({ ...document, lines: document.lines.map((line) => remap.has(line.projectId) ? { ...line, projectId: remap.get(line.projectId)! } : line) }));
  return { projects: nextProjects, documents, settings: { ...data.settings, nextProjectSequence: nextSequence } };
}

