type SpendMetrics = { quotations: number; po: number; actual: number; open: number };
function spendMetrics(data: StudioData, projectId?: string, spendingLineId?: string, quarter?: Quarter): SpendMetrics {
  const lines = data.documents.flatMap((document) => document.lines.map((line) => ({ document, line }))).filter(({ line }) => (!projectId || line.projectId === projectId) && (!spendingLineId || line.spendingLineId === spendingLineId) && (!quarter || line.spendQuarter === quarter));
  const quotations = lines.filter(({ document }) => document.type === "Quotation").reduce((sum, row) => sum + reportingAmount(data, number(row.line.amount), row.line.currency), 0);
  const invoiceLines = lines.filter(({ document }) => document.type === "Invoice");
  const actual = invoiceLines.reduce((sum, row) => sum + reportingAmount(data, number(row.line.amount), row.line.currency), 0);
  const purchaseOrders = lines.filter(({ document }) => document.type === "Purchase order");
  const po = purchaseOrders.reduce((sum, row) => sum + reportingAmount(data, number(row.line.amount), row.line.currency), 0);
  const open = purchaseOrders.reduce((sum, row) => { const converted = invoiceLines.filter(({ line }) => line.sourceDocumentLineId === row.line.id || (!line.sourceDocumentLineId && line.sourceDocumentId === row.document.id && line.projectId === row.line.projectId && line.spendingLineId === row.line.spendingLineId)).reduce((invoiceSum, invoice) => invoiceSum + reportingAmount(data, number(invoice.line.amount), invoice.line.currency), 0); return sum + Math.max(0, reportingAmount(data, number(row.line.amount), row.line.currency) - converted); }, 0);
  return { quotations, po, actual, open };
}
function projectMonitor(data: StudioData, project: Project) { const planned = projectPlannedReporting(data, project); const metrics = spendMetrics(data, project.id); const forecast = metrics.actual + metrics.open; const remainingHeadroom = approvedReporting(data, project) - forecast; const status = planned <= 0 && approvedReporting(data, project) > 0 ? "Unphased approved amount" : forecast > approvedReporting(data, project) ? "Overspending" : planned < approvedReporting(data, project) * 0.85 ? "Potential underspend" : "Within plan"; return { planned, ...metrics, forecast, remainingHeadroom, status, needsAdjustment: status === "Overspending" || status === "Potential underspend" || revisionStatus(project) === "Adjusted" }; }
  function projectQuarterPlan(data: StudioData, project: Project, quarter: Quarter) { return project.lines.reduce((sum, line) => { if (!line.quarters.includes(quarter)) return sum; const phased = quarterAmount(data, line, quarter); const fallback = lineTotalReporting(data, line) / Math.max(1, line.quarters.length); return sum + (phased > 0 ? phased : fallback); }, 0); }
  function projectQuarterPlanTotal(data: StudioData, project: Project) { return QUARTERS.reduce((sum, quarter) => sum + projectQuarterPlan(data, project, quarter), 0); }
  function phaseApprovedAmount(data: StudioData, project: Project, quarter: Quarter) { const total = projectQuarterPlanTotal(data, project); if (total <= 0) return project.spendingQuarters.includes(quarter) ? approvedReporting(data, project) / Math.max(1, project.spendingQuarters.length) : 0; return approvedReporting(data, project) * projectQuarterPlan(data, project, quarter) / total; }
function quoteDelimited(value: unknown) { const text = safeSpreadsheetText(value); return /[",\r\n\t]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text; }

