function DocumentEditor({ data, setData, document, onClose }: { data: StudioData; setData: Dispatch<SetStateAction<StudioData>>; document: SpendDocument; onClose: () => void }) {
  const [draft, setDraft] = useState<SpendDocument>(clone(document));
  const update = (patch: Partial<SpendDocument>) => setDraft((current) => ({ ...current, ...patch }));
  const updateLine = (id: string, patch: Partial<DocumentLine>) => setDraft((current) => ({ ...current, lines: current.lines.map((line) => line.id === id ? { ...line, ...patch } : line) }));
  const addLine = () => { const project = data.projects[0]; const line = project?.lines[0]; if (!project || !line) return; setDraft((current) => ({ ...current, lines: [...current.lines, { id: newId("document-line"), projectId: project.id, spendingLineId: line.id, description: itemFor(data, line.spendingItemId)?.name ?? "", amount: 0, currency: data.settings.currency, spendQuarter: data.settings.currentQuarter }] })); };
  const removeLine = (id: string) => { if (confirmRemoval("this document line")) setDraft((current) => ({ ...current, lines: current.lines.filter((line) => line.id !== id) })); };
  const save = () => { setData((current) => ({ ...current, documents: current.documents.some((candidate) => candidate.id === draft.id) ? current.documents.map((candidate) => candidate.id === draft.id ? draft : candidate) : [...current.documents, draft] })); onClose(); };
  const total = draft.lines.reduce((sum, line) => sum + reportingAmount(data, line.amount, line.currency), 0);
  return <section className="document-editor"><div className="screen-heading"><div><span className="eyebrow">Synthetic document record</span><h3>{data.documents.some((candidate) => candidate.id === draft.id) ? "Edit document" : "Add document"}</h3><p className="muted">One document may contain lines across multiple projects, requirements and optional sourcing allocations.</p></div><AppButton kind="quiet" onClick={onClose}>Close</AppButton></div><div className="field-grid four-col"><div className="field"><label htmlFor="doc-type"><Label>Document type</Label></label><select id="doc-type" value={draft.type} onChange={(event) => update({ type: event.target.value as DocumentType })}><option>Quotation</option><option>Purchase order</option><option>Invoice</option></select></div><div className="field"><label htmlFor="doc-reference"><Label>Reference</Label></label><input id="doc-reference" value={draft.reference} onChange={(event) => update({ reference: event.target.value })} placeholder="PO-MKT-MIXED" /></div><div className="field field-span-2"><label htmlFor="doc-file"><Label>Quotation / PO / Invoice file reference</Label></label><input id="doc-file" value={draft.fileName} onChange={(event) => update({ fileName: event.target.value })} placeholder="document.pdf" /></div><div className="field"><label htmlFor="doc-date"><Label>Date</Label></label><input id="doc-date" type="date" value={draft.date} onChange={(event) => update({ date: event.target.value })} /></div><div className="field"><label htmlFor="doc-vendor"><Label>Vendor</Label></label><input id="doc-vendor" value={draft.vendor} onChange={(event) => update({ vendor: event.target.value })} /></div><div className="field"><label htmlFor="doc-status"><Label>Status</Label></label><input id="doc-status" value={draft.status} onChange={(event) => update({ status: event.target.value })} /></div></div><div className="document-lines-editor"><div className="subsection-heading"><div><span className="eyebrow">Line allocation</span><h4>Attribute every line to a project, requirement and optional allocation</h4></div><AppButton kind="secondary" onClick={addLine}>Add line</AppButton></div>{draft.lines.map((line) => { const project = data.projects.find((candidate) => candidate.id === line.projectId); const requirement = project?.lines.find((candidate) => candidate.id === line.spendingLineId); return <div className="document-edit-line" key={line.id}><div className="field"><label htmlFor={`document-project-${line.id}`}><Label>Project ID</Label></label><select id={`document-project-${line.id}`} value={line.projectId} onChange={(event) => { const nextProject = data.projects.find((candidate) => candidate.id === event.target.value); const nextLine = nextProject?.lines[0]; updateLine(line.id, { projectId: event.target.value, spendingLineId: nextLine?.id ?? "", allocationId: undefined, description: nextLine?.itemNameSnapshot ?? itemFor(data, nextLine?.spendingItemId ?? "")?.name ?? "" }); }}>{data.projects.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.id} · {candidate.name}</option>)}</select></div><div className="field"><label htmlFor={`document-item-${line.id}`}><Label>Spending requirement</Label></label><select id={`document-item-${line.id}`} value={line.spendingLineId} onChange={(event) => { const planned = project?.lines.find((candidate) => candidate.id === event.target.value); updateLine(line.id, { spendingLineId: event.target.value, allocationId: undefined, description: planned?.itemNameSnapshot ?? itemFor(data, planned?.spendingItemId ?? "")?.name ?? "" }); }}>{project?.lines.map((planned) => <option key={planned.id} value={planned.id}>{planned.itemNameSnapshot ?? itemFor(data, planned.spendingItemId)?.name ?? "Untitled item"}</option>)}</select></div><div className="field"><label htmlFor={`document-allocation-${line.id}`}><Label>Sourcing allocation</Label></label><select id={`document-allocation-${line.id}`} value={line.allocationId ?? ""} onChange={(event) => updateLine(line.id, { allocationId: event.target.value || undefined })}><option value="">Requirement-level link</option>{lineAllocations(requirement ?? { id: "", spendingItemId: "", quantity: 0, unitPrice: 0, unitCurrency: data.settings.currency, quarters: [] }).map((allocation) => <option key={allocation.id} value={allocation.id}>{allocation.vendorOrWarehouse || allocation.sourceType} · {allocation.sourceCountry || "Country pending"}</option>)}</select></div><div className="field"><label htmlFor={`document-description-${line.id}`}><Label>Line description</Label></label><input id={`document-description-${line.id}`} value={line.description} onChange={(event) => updateLine(line.id, { description: event.target.value })} /></div><div className="field"><label htmlFor={`document-amount-${line.id}`}><Label>Amount</Label></label><div className="currency-input"><input id={`document-amount-${line.id}`} type="number" min="0" step="0.01" value={line.amount} onChange={(event) => updateLine(line.id, { amount: number(event.target.value) })} /><select aria-label="Document line currency" value={line.currency} onChange={(event) => updateLine(line.id, { currency: event.target.value })}>{CURRENCIES.map((currency) => <option key={currency}>{currency}</option>)}</select></div></div><div className="field"><label htmlFor={`document-quarter-${line.id}`}><Label>Spend quarter</Label></label><select id={`document-quarter-${line.id}`} value={line.spendQuarter} onChange={(event) => updateLine(line.id, { spendQuarter: event.target.value as Quarter })}>{QUARTERS.map((quarter) => <option key={quarter}>{quarter}</option>)}</select></div>{draft.type === "Invoice" ? <div className="field field-span-2"><label htmlFor={`document-source-${line.id}`}><Label>Converted from exact PO line</Label></label><select id={`document-source-${line.id}`} value={line.sourceDocumentLineId ?? ""} onChange={(event) => updateLine(line.id, { sourceDocumentLineId: event.target.value || undefined, sourceDocumentId: data.documents.find((candidate) => candidate.lines.some((candidateLine) => candidateLine.id === event.target.value))?.id })}><option value="">Choose source PO line</option>{data.documents.filter((candidate) => candidate.type === "Purchase order").flatMap((candidate) => candidate.lines.map((poLine) => <option key={poLine.id} value={poLine.id}>{candidate.reference} · {poLine.projectId} · {poLine.description}</option>))}</select></div> : null}<AppButton kind="quiet" onClick={() => removeLine(line.id)}>Remove line</AppButton></div>; })}</div><div className="document-total-row"><span>Document total in reporting currency</span><strong>{formatMoney(total, data.settings.currency)}</strong></div><div className="conversion-note"><strong>Linkage rule:</strong> invoice lines reference an exact PO line; allocation links are optional. The converted amount reduces that PO line&apos;s open commitment and is not counted twice.</div><div className="form-actions"><AppButton kind="primary" onClick={save}>Save document record</AppButton></div></section>;
}

